#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    // Two-pass parallel scan:
    // 1) Each thread computes a local prefix sum over its chunk and records chunk sum.
    // 2) Compute prefix sums of chunk sums (serial, small).
    // 3) Add chunk offsets to each element in parallel.
    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        { max_threads = omp_get_num_threads(); }
    }

    std::vector<double> chunk_sums(static_cast<std::size_t>(max_threads), 0.0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        // Use the actual number of threads used in this region.
        // Ensure chunk_sums is large enough (it is, because max_threads >= nt).
        const std::size_t chunk = (n + static_cast<std::size_t>(nt) - 1) / static_cast<std::size_t>(nt);
        const std::size_t begin = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end   = (begin + chunk < n) ? (begin + chunk) : n;

        double running = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            running += x[i];
            output[i] = running;
        }
        chunk_sums[static_cast<std::size_t>(tid)] = running;
    }

    // Compute offsets for each chunk (exclusive prefix of chunk_sums).
    // offset[t] = sum_{k < t} chunk_sums[k]
    std::vector<double> offsets(static_cast<std::size_t>(chunk_sums.size()), 0.0);
    for (std::size_t t = 1; t < offsets.size(); ++t) {
        offsets[t] = offsets[t - 1] + chunk_sums[t - 1];
    }

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(nt) - 1) / static_cast<std::size_t>(nt);
        const std::size_t begin = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end   = (begin + chunk < n) ? (begin + chunk) : n;

        const double add = offsets[static_cast<std::size_t>(tid)];
        if (add != 0.0) {
            for (std::size_t i = begin; i < end; ++i) {
                output[i] += add;
            }
        }
    }
}
